mapper.select:

SELECT (SELECT oldest.applied_base_rate
        FROM repayment_schedule oldest
        WHERE oldest.loan_account_id = #{loanAccountId}
          AND oldest.repayment_schedule_status_id = #{overdue}
        ORDER BY oldest.scheduled_date
        LIMIT 1) AS applied_base_rate,
       (SELECT oldest.applied_additional_rate
        FROM repayment_schedule oldest
        WHERE oldest.loan_account_id = #{loanAccountId}
          AND oldest.repayment_schedule_status_id = #{overdue}
        ORDER BY oldest.scheduled_date
        LIMIT 1) AS applied_additional_rate,
       COALESCE(SUM(rs.scheduled_interest - rs.paid_interest), 0) AS carried_interest,
       COALESCE(SUM(rs.scheduled_principal - rs.paid_principal), 0) AS carried_overdue_principal,
       (SELECT COALESCE(SUM(idc.delinquency_charge - idc.paid_delinquency_charge), 0)
        FROM installment_delinquency_charge idc
        JOIN repayment_schedule charged ON charged.repayment_schedule_id = idc.repayment_schedule_id
        WHERE charged.loan_account_id = #{loanAccountId}
          AND charged.repayment_schedule_status_id = #{overdue}) AS carried_delinquency_charge
FROM repayment_schedule rs
WHERE rs.loan_account_id = #{loanAccountId}
  AND rs.repayment_schedule_status_id = #{overdue}

