UPDATE loan_acceleration
SET paid_carried_delinquency_charge = paid_carried_delinquency_charge + #{amount}
WHERE loan_acceleration_id = #{loanAccelerationId}

UPDATE loan_acceleration
SET paid_carried_interest = paid_carried_interest + #{amount}
WHERE loan_acceleration_id = #{loanAccelerationId}

UPDATE loan_acceleration
SET paid_carried_overdue_principal = paid_carried_overdue_principal + #{amount}
WHERE loan_acceleration_id = #{loanAccelerationId}
